def verify_solution(result, num_weeks, num_groups, group_size):
    num_golfers = num_groups * group_size
    if len(result) != num_weeks * num_golfers:
        return False, "Incorrect length"

    # Check each week
    for w in range(num_weeks):
        week_groups = [[] for _ in range(num_groups)]
        for p in range(num_golfers):
            group = result[w * num_golfers + p]
            if group < 0 or group >= num_groups:
                return False, f"Invalid group {group} for golfer {p} in week {w}"
            week_groups[group].append(p)

        for g in range(num_groups):
            if len(week_groups[g]) != group_size:
                return False, f"Group {g} in week {w} has size {len(week_groups[g])}, expected {group_size}"

    # Check pairs
    pairs = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            group_members = [p for p in range(num_golfers) if result[w * num_golfers + p] == g]
            for i in range(len(group_members)):
                for j in range(i + 1, len(group_members)):
                    p1, p2 = group_members[i], group_members[j]
                    pair = tuple(sorted((p1, p2)))
                    if pair in pairs:
                        return False, f"Pair {pair} in same group in week {w} and week {pairs[pair]}"
                    pairs[pair] = w
    return True, "Valid"

